/**
 * Generate _redirects with A-class 301s + SPA fallback.
 * Runs in build chain before wrangler deploy.
 */
import fs from 'node:fs';
import { A_CLASS } from './lib/blog-a-class.mjs';

const LANGS = [
  'zh-CN','zh-TW','ja','ko','de','fr','es','it','pt','ru','ar','hi','th','vi','id',
  'tr','pl','nl','sv','no','da','fi','el','cs','hu','ro','uk','he','ms'
];

const lines = [
  '# Auto-generated by scripts/generate-redirects.mjs',
  '# Canonical host',
  'https://www.cooldrivepro.com/* https://cooldrivepro.com/:splat 301',
  '',
  '# Legacy / unsupported language prefixes',
  '/zh /zh-CN/ 301',
  '/zh/* /zh-CN/:splat/ 301',
  '/zh-cn /zh-CN/ 301',
  '/zh-cn/* /zh-CN/:splat/ 301',
  '/zh-tw /zh-TW/ 301',
  '/zh-tw/* /zh-TW/:splat/ 301',
  '/bn / 301',
  '/bn/* /:splat/ 301',
  '',
  '# Accidental double-locale URLs from old language switching',
  '/:outer/zh/* /zh-CN/:splat/ 301',
  '/:outer/zh-cn/* /zh-CN/:splat/ 301',
  '/:outer/zh-tw/* /zh-TW/:splat/ 301',
  '/:outer/bn/* /:splat/ 301',
  ...LANGS.map((lang) => `/:outer/${lang}/* /${lang}/:splat/ 301`),
  '',
  '# English-only commercial hubs: localized copies redirect to the canonical English hub until translated',
  '/:lang/solutions/* /solutions/:splat/ 301',
  '/:lang/compare/* /compare/:splat/ 301',
  '',
  '# Legacy commerce and feature URLs',
  '/shop /products/ 301',
  '/shop/ /products/ 301',
  '/features/heat-cool /products/heating-cooling-ac/ 301',
  '/features/heat-cool/ /products/heating-cooling-ac/ 301',
  '/:lang/features/heat-cool /:lang/products/heating-cooling-ac/ 301',
  '/:lang/features/heat-cool/ /:lang/products/heating-cooling-ac/ 301',
  '',
  '# Legacy product slugs that used to fall through to the home canonical',
  '/products/vs02-pro /products/top-mounted-ac/ 301',
  '/products/vs02-pro/ /products/top-mounted-ac/ 301',
  '/products/vs02 /products/top-mounted-ac/ 301',
  '/products/vs02/ /products/top-mounted-ac/ 301',
  '/products/vx3000 /products/mini-split-ac/ 301',
  '/products/vx3000/ /products/mini-split-ac/ 301',
  '/products/vx3000sp /products/mini-split-ac/ 301',
  '/products/vx3000sp/ /products/mini-split-ac/ 301',
  '/products/vx3000-sp /products/mini-split-ac/ 301',
  '/products/vx3000-sp/ /products/mini-split-ac/ 301',
  ...LANGS.flatMap((lang) => [
    `/${lang}/products/vs02-pro /${lang}/products/top-mounted-ac/ 301`,
    `/${lang}/products/vs02-pro/ /${lang}/products/top-mounted-ac/ 301`,
    `/${lang}/products/vs02 /${lang}/products/top-mounted-ac/ 301`,
    `/${lang}/products/vs02/ /${lang}/products/top-mounted-ac/ 301`,
    `/${lang}/products/vx3000 /${lang}/products/mini-split-ac/ 301`,
    `/${lang}/products/vx3000/ /${lang}/products/mini-split-ac/ 301`,
    `/${lang}/products/vx3000sp /${lang}/products/mini-split-ac/ 301`,
    `/${lang}/products/vx3000sp/ /${lang}/products/mini-split-ac/ 301`,
    `/${lang}/products/vx3000-sp /${lang}/products/mini-split-ac/ 301`,
    `/${lang}/products/vx3000-sp/ /${lang}/products/mini-split-ac/ 301`,
  ]),
  '',
  '# Data-only blog endpoints that were accidentally exposed as article URLs',
  '/blog/related-posts /blog/ 301',
  '/blog/related-posts/ /blog/ 301',
  ...LANGS.flatMap((lang) => [
    `/${lang}/blog/related-posts /${lang}/blog/ 301`,
    `/${lang}/blog/related-posts/ /${lang}/blog/ 301`,
  ]),
  '',
  '# A-class geo-template spam → country pillar (301 permanent)',
  '',
];

for (const [oldSlug, newSlug] of Object.entries(A_CLASS)) {
  if (!newSlug) continue; // no pillar target → rely on noindex alone
  // English (default, no lang prefix)
  lines.push(`/blog/${oldSlug} /blog/${newSlug}/ 301`);
  lines.push(`/blog/${oldSlug}/ /blog/${newSlug}/ 301`);
  // All 29 other langs
  for (const lang of LANGS) {
    lines.push(`/${lang}/blog/${oldSlug} /${lang}/blog/${newSlug}/ 301`);
    lines.push(`/${lang}/blog/${oldSlug}/ /${lang}/blog/${newSlug}/ 301`);
  }
}

// Legacy / mistyped blog slugs are handled in workers/pages-worker.js
// because _redirects already exceeds Cloudflare Pages' rule limit.

const FEATURE_ALIASES = {
  quiet: 'noise',
  install: 'installation',
  solar: 'power',
  smart: 'battery',
};

lines.push('', '# Legacy feature slugs from old sitemap → current feature pages');
for (const [oldSlug, newSlug] of Object.entries(FEATURE_ALIASES)) {
  lines.push(`/features/${oldSlug} /features/${newSlug}/ 301`);
  lines.push(`/features/${oldSlug}/ /features/${newSlug}/ 301`);
  for (const lang of LANGS) {
    lines.push(`/${lang}/features/${oldSlug} /${lang}/features/${newSlug}/ 301`);
    lines.push(`/${lang}/features/${oldSlug}/ /${lang}/features/${newSlug}/ 301`);
  }
}

lines.push(
  '',
  '# Cloudflare Pages serves prerendered /path/index.html pages at /path/.',
  '# Do not strip trailing slashes here; doing so creates a /path ⇄ /path/ loop.',
  '# SPA fallback — must stay last',
  '/*  /index.html  200',
  '',
);

fs.writeFileSync('client/public/_redirects', lines.join('\n'));
console.log(`Generated ${lines.length} lines in client/public/_redirects`);
const rules = Object.entries(A_CLASS).filter(([,t])=>t).length;
console.log(`  ${rules} A-class slugs × 30 langs × slash/no-slash = ${rules*60} 301 redirects`);

// Cloudflare Pages silently drops rules past its limit (~2296 lines hit in 2026-05).
// Route any new legacy 301s through workers/pages-worker.js LEGACY_BLOG_SLUG_REDIRECTS instead.
const SOFT_CEILING = 2200;
const HARD_CEILING = 2280;
if (lines.length >= HARD_CEILING) {
  console.error(`\n[generate-redirects] FATAL: ${lines.length} lines >= hard ceiling ${HARD_CEILING}. Cloudflare Pages will silently drop tail rules. Move new 301s into workers/pages-worker.js LEGACY_BLOG_SLUG_REDIRECTS.`);
  process.exit(1);
}
if (lines.length >= SOFT_CEILING) {
  console.warn(`\n[generate-redirects] WARN: ${lines.length} lines >= soft ceiling ${SOFT_CEILING}. Future legacy 301s should go into workers/pages-worker.js, not _redirects.`);
}
